def count_X(tup, elem):
    count = 0
    for x in tup:
        if x == elem:
            count += 1
    return count

assert count_X((10, 8, 5, 2, 10, 15, 10, 8, 5, 8, 8, 2), 4) == 0

def bell_number(n):
    bell = [0 for i in range(n+1)]
    bell[0] = 1

    for i in range(1, n+1):
        bell[i] = 0
        for j in range(i):
            bell[i] += bell[j] * bell[i-j-1]

    return bell[n]

