def multiply_num(nums):
    result = 1
    for num in nums:
        result *= num
    return result / len(nums)

def find_length(binary_string):
    max_diff = 0
    count_0 = 0
    count_1 = 0

    for char in binary_string:
        if char == '0':
            count_0 += 1
        else:
            count_1 += 1

        if count_1 - count_0 > max_diff:
            max_diff = count_1 - count_0

    return max_diff

def count_Set_Bits(n):
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

def k_smallest_pairs(arr1, arr2, k):
    pairs = []
    for i in range(min(k, len(arr1))):
        for j in range(min(k - i, len(arr2))):
            pairs.append([arr1[i], arr2[j]])
    return pairs[:k]

