def eulerian_num(n, m):
    if m == 0:
        return 1
    elif n == 1:
        return 1
    else:
        return (n - m) * eulerian_num(n - 1, m - 1) + eulerian_num(n - 1, m)

# Test the function
assert eulerian_num(3, 1) == 4

def is_sublist(lst, sublst):
    for i in range(len(lst) - len(sublst) + 1):
        if lst[i:i+len(sublst)] == sublst:
            return True
    return False

